-- writing_expression.practice_examples_payload의 각 추가 예문에
-- sentenceTranslateWords(해석을 단어로 나눈 배열)와
-- sentenceTranslateWordChoices(오답을 섞어 순서를 뒤섞은 선택지)를 추가한다.
--
-- 표현 1,938건 × 예문 4건 = 7,752건이 대상이다. 기존 키는 그대로 두고 두 키를 병합한다.
--
-- 예외로 id 48, 178, 188, 194의 예문 하나씩은 sentenceTranslation도 함께 바꾼다. 해석이
-- '그렇게 하자! / 좋은 계획이야!'처럼 두 가지로 병기돼 있어, 그대로 두면 한국어 퀴즈 화면에는
-- 두 문장이 보이는데 조립할 수 있는 단어는 한 문장분뿐이라 풀 수 없게 된다. 더 자연스러운
-- 해석 하나만 남긴다.
-- 예문은 sentenceText로 매칭하되, 한 표현 안에 같은 문장이 두 번 나오는 id 330과 1688은
-- 순번(ord)으로 매칭해 중복 매칭을 피한다.
--
-- 트랜잭션은 Flyway가 관리하므로 BEGIN/COMMIT을 두지 않는다.

UPDATE writing_expression w SET practice_examples_payload = (
  SELECT jsonb_agg(e.elem || COALESCE(p.patch, '{}'::jsonb) ORDER BY e.ord)
  FROM jsonb_array_elements(w.practice_examples_payload) WITH ORDINALITY AS e(elem, ord)
  LEFT JOIN (VALUES
    ('There''s nothing like a cold beer on a hot day.', '{"sentenceTranslateWords": ["더운", "날엔", "시원한", "맥주만", "한", "게", "없지"], "sentenceTranslateWordChoices": ["맥주만", "게", "없지", "추운", "날엔", "더운", "시원한", "커피만", "한", "밤엔"]}'::jsonb),
    ('There''s nothing like mom''s cooking.', '{"sentenceTranslateWords": ["엄마", "밥만", "한", "게", "없어"], "sentenceTranslateWordChoices": ["없어", "한", "엄마", "빵만", "그리워", "밥만", "아빠", "게"]}'::jsonb),
    ('There''s nothing like a good night''s sleep.', '{"sentenceTranslateWords": ["푹", "자는", "것만큼", "좋은", "게", "없어"], "sentenceTranslateWordChoices": ["나쁜", "없어", "자는", "푹", "좋은", "조금", "것만큼", "먹는", "게"]}'::jsonb),
    ('There''s nothing like traveling with friends.', '{"sentenceTranslateWords": ["친구들이랑", "여행하는", "것만", "한", "게", "없지"], "sentenceTranslateWordChoices": ["친구들이랑", "없었지", "공부하는", "여행하는", "게", "것만", "한", "가족이랑", "없지"]}'::jsonb)
  ) AS p(stext, patch) ON p.stext = e.elem->>'sentenceText'
) WHERE w.id = 1;

UPDATE writing_expression w SET practice_examples_payload = (
  SELECT jsonb_agg(e.elem || COALESCE(p.patch, '{}'::jsonb) ORDER BY e.ord)
  FROM jsonb_array_elements(w.practice_examples_payload) WITH ORDINALITY AS e(elem, ord)
  LEFT JOIN (VALUES
    ('Her voice blows my mind every time.', '{"sentenceTranslateWords": ["그녀", "목소리는", "들을", "때마다", "소름", "돋아"], "sentenceTranslateWordChoices": ["때마다", "가끔", "돋았어", "들을", "그녀", "돋아", "목소리는", "소름", "표정은"]}'::jsonb),
    ('The special effects blew my mind.', '{"sentenceTranslateWords": ["특수효과가", "끝내줬어"], "sentenceTranslateWordChoices": ["별로였어", "특수효과가", "무서웠어", "끝내줬어", "자막이"]}'::jsonb),
    ('This fact will blow your mind.', '{"sentenceTranslateWords": ["이", "사실", "들으면", "깜짝", "놀랄걸"], "sentenceTranslateWordChoices": ["소문", "들으면", "놀랐어", "이", "보면", "깜짝", "사실", "놀랄걸"]}'::jsonb),
    ('The concert was mind-blowing.', '{"sentenceTranslateWords": ["콘서트가", "진짜", "압도적이었어"], "sentenceTranslateWordChoices": ["영화가", "조금", "별로였어", "콘서트가", "진짜", "압도적이었어"]}'::jsonb)
